const E=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const A=(url,title)=>'<a href="'+E(url)+'" target="_blank" rel="noopener noreferrer">'+E(title)+' ↗</a>';
const vocabularyGuide=Object.fromEntries([["nation","a community of people connected by a political identity, history, and traditions"],["confederacy","an alliance of nations or political communities cooperating while retaining distinct identities"],["oral tradition","knowledge and history passed between generations through spoken accounts"],["community","people connected by place, relationships, interests, or shared responsibilities"],["governance","the ways a community makes decisions and establishes responsibilities"],["resource","a material, living thing, or condition used to meet needs"],["consensus","a decision reached through broad agreement rather than a simple winner-take-all vote"],["territory","land associated with a nation, community, or political authority"],["trade route","a path used to exchange goods, services, and ideas"],["navigation","planning and following a route across land or water"],["sponsorship","support, often money or authority, provided for an undertaking"],["colonization","the process of establishing outside political control and settlement in a place"],["encounter","a meeting between people or groups, sometimes with very unequal power"],["perspective","the viewpoint shaped by someone's experience, position, and interests"],["primary source","evidence created during an event or by people with direct experience of it"],["bias","a preference or perspective that can shape how information is presented"],["pathogen","a microorganism or agent that can cause disease"],["exchange","the movement or sharing of goods, ideas, organisms, and practices"],["ecology","the relationships between living things and their environments"],["consequence","a result or effect of a decision or event"],["colony","a settlement or territory governed by an outside power"],["region","an area sharing geographic, historical, or cultural characteristics"],["subsistence","the means of obtaining food and other necessities of life"],["inequality","an uneven distribution of rights, opportunities, wealth, or power"],["enslavement","the coercive condition in which people are held as property or forced into labor without freedom"],["indenture","an agreement requiring work for a fixed term, often to repay passage or a debt"],["plantation","a large agricultural estate, historically often reliant on enslaved labor"],["resistance","actions taken to oppose control, injustice, or unwanted change"],["toleration","allowing beliefs or practices even when one does not share them"],["established church","a church formally supported or recognized by government"],["identity","the qualities and connections through which people understand themselves"],["exclusion","keeping people from rights, opportunities, places, or decisions"],["proprietary colony","a colony governed under a charter granting authority to a private proprietor"],["chesapeake","the region around the Chesapeake Bay, including parts of Maryland and Virginia"],["tobacco","a crop central to the colonial Chesapeake economy, cultivated through coercive labor systems"],["piscataway","an Indigenous people with enduring connections to the Potomac and southern Maryland region"],["empire","a state or political system extending authority over other peoples or territories"],["alliance","a relationship formed for cooperation or shared goals"],["territorial claim","an assertion of authority or ownership over a particular area"],["diplomacy","negotiation and relationship-building between nations or political groups"],["seven years’ war","a global war of 1756–1763 involving European empires and their allies"],["ohio valley","the region surrounding the Ohio River, contested by empires and Indigenous nations"],["treaty","a formal agreement between nations or governments"],["sovereignty","the authority of a people or nation to govern itself"],["stamp act","a 1765 British tax on specified printed materials in the American colonies"],["boycott","refusal to buy or use goods as a form of protest"],["representation","the act of speaking or making decisions on behalf of others in government"],["petition","a formal written request to an authority"],["grievance","a complaint about an injustice or harmful policy"],["independence","freedom from the political control of another power"],["natural rights","rights argued to belong to people by virtue of being human"],["congress","a formal assembly of representatives or lawmakers"],["turning point","an event that significantly changes how a situation develops"],["saratoga","the 1777 American victories that helped secure a French alliance"],["yorktown","the 1781 siege and British surrender that proved decisive in the Revolutionary War"],["patriot","in the American Revolution, a person who supported independence from Britain"],["loyalist","in the American Revolution, a person who supported continued ties to the British Crown"],["agency","people's capacity to make choices and act within historical constraints"],["emancipation","the freeing of people from enslavement"],["liberty","freedom, including rights and choices, whose meaning and access have changed historically"],["citizenship","membership in a political community with rights and responsibilities"],["confederation","an association of states that retain considerable governing authority"],["ratification","the formal approval of a treaty, constitution, or legal measure"],["ordinance","an authoritative law or regulation"],["taxation","the government collection of money to fund public purposes"],["federalism","division of government authority between national and state governments"],["compromise","an agreement in which parties make concessions to resolve differences"],["amendment","a formal change or addition to a constitution or law"],["due process","fair legal procedures required before government may deprive someone of protected rights"],["precedent","a decision or practice that serves as an example for later actions"],["cabinet","senior executive advisers who head major departments"],["executive","the branch responsible for carrying out and enforcing laws"],["neutrality","a policy of not taking sides in a particular conflict"],["faction","an organized group with shared political views or interests"],["federalist","a supporter of stronger national authority; also a member of the 1790s Federalist political movement"],["democratic-republican","a member of the 1790s political movement associated with Jefferson and Madison"],["partisan","strongly supporting one political group or viewpoint"],["excise tax","a tax charged on a particular good or activity"],["rebellion","organized opposition to established government authority, sometimes using force"]].map(([term,definition])=>[term.toLowerCase(),definition]));
Object.assign(vocabularyGuide,{"region":"an area grouped using defined physical, cultural, historical, or political criteria","scale":"the size of a geographic area being studied or the ratio represented on a map","physical geography":"the study of landforms, climate, water, and other physical features","cultural boundary":"a changing border between areas associated with different cultural practices","identity":"how people understand and describe belonging to people, places, and traditions","adaptation":"a change in practice or technology in response to conditions","geographic determinism":"the incorrect idea that geography alone determines a society's history","cultural geography":"the study of how people and places shape one another","cultural landscape":"land or a setting shaped by human activity over time","built environment":"human-constructed surroundings such as roads, houses, and cities","continuity":"a practice or relationship that persists through historical change","land use":"the way people manage or occupy land for different purposes","migration":"the movement of people between locations, short-term or long-term","displacement":"movement away from home, often forced by danger, violence, or other pressures","push factor":"a condition making someone consider leaving a place","pull factor":"a condition attracting people toward a different place","population":"the people living in a defined place or area","census":"a systematic count or survey of people conducted at a particular time","demography":"the study of the size and characteristics of populations","forced migration":"movement of people caused by coercion, violence, or threat","diaspora":"communities living outside an ancestral homeland while keeping or reshaping connections","exchange":"the movement or sharing of goods, knowledge, or practices","caravan":"a group of travelers moving together, often across difficult routes","oasis":"a place with accessible water within an arid region","network":"a set of places and people connected by exchange or movement","intermediary":"a person or community linking other participants in an exchange","monsoon":"a seasonal wind pattern that often brings changes in rainfall","maritime":"related to the sea, sailing, and waterborne travel","port":"a place where vessels load, unload, or shelter","navigation":"planning and carrying out travel using routes, conditions, and location","sahel":"the broad transition zone south of the Sahara with varied environments and communities","mali empire":"a major medieval West African state associated with trade and political power","pilgrimage":"a journey made for religious purposes","urbanization":"the process through which urban settlements grow or become more important","commerce":"buying, selling, and other economic exchange","inequality":"an uneven distribution of resources, rights, or power","authority":"a recognized or claimed right to make or enforce decisions","legitimacy":"the acceptance of an institution or leader's right to govern","institution":"an established organization or set of rules serving a social purpose","participation":"taking part in decisions or activities","scarcity":"a condition in which available resources cannot meet every possible demand","opportunity cost":"the value of the next-best option that must be given up when a choice is made","allocation":"the distribution of limited resources among different uses","interdependence":"reliance of people or communities on one another","strategic location":"a place important for transport, defense, or control of resources","territory":"land claimed, occupied, or governed by a community or political authority","infrastructure":"the systems, facilities, and networks that support society","geopolitics":"the interaction of geography, political interests, and power","belief tradition":"historically connected religious or philosophical beliefs and practices","cultural exchange":"interaction through which communities share or adapt traditions and ideas","diversity":"the existence of meaningful differences within a group or among groups","cultural diffusion":"the spreading and adaptation of ideas or practices between communities","innovation":"a new or changed method, tool, idea, or practice","evidence":"information that can support or challenge a historical claim","diplomacy":"negotiation and relations among communities or political groups","alliance":"an agreement to cooperate toward shared aims","conflict":"a dispute or struggle involving incompatible interests or actions","perspective":"a particular viewpoint shaped by experience, purpose, and position","environment":"the physical and living surroundings that shape available choices","livelihood":"the activities people use to support their lives","settlement":"a place where people establish a community or residence","natural resource":"a material or condition from nature that people use","distribution":"how something is spread across a region or among people","extraction":"the removal of raw materials from the environment","sustainability":"the ability to support needs over time without unacceptable long-term harm","hazard":"a possible source of harm such as a flood or drought","resilience":"the capacity to respond and adapt to disturbances","mitigation":"steps designed to reduce harm or risk","trade-off":"a compromise in which gaining one benefit involves giving something else up"});
Object.assign(vocabularyGuide,{"charter":"an official document granting authority or specifying rights and obligations","imperial policy":"a government's decisions about how it controls overseas territories","powhatan":"the name often used for the paramount chiefdom of Tsenacommacah, including multiple Indigenous communities","assembly":"a group of people convened to discuss or make political decisions","franchise":"the legal right to vote in elections","governor":"an official entrusted with executive authority over a territory or state","representation":"the way people or their interests participate through decision-makers","chattel slavery":"a system legally treating enslaved human beings as property","middle passage":"the forced Atlantic voyage of Africans transported into slavery","plantation":"a large agricultural estate, often sustained through coerced labor","resistance":"actions opposing or challenging a system, decision, or form of control","parliamentary sovereignty":"the asserted supreme lawmaking authority of Parliament","stamp act":"a British tax measure passed in 1765 affecting many printed documents","nonimportation":"a protest strategy involving refusal to purchase imported goods","petition":"a formal written request for action, redress, or change","consent of governed":"the principle that legitimate government draws authority from those subject to it","grievance":"a specific complaint about an alleged injustice or harmful action","natural rights":"rights believed to belong to people by nature rather than by government grant","independence":"political freedom from control by another country or governing authority","saratoga":"the 1777 Revolutionary War campaign that helped secure the French alliance","yorktown":"the 1781 Virginia campaign ending with a major British surrender","treaty of paris":"the 1783 agreement in which Britain recognized U.S. independence","gradual emancipation":"a legal process ending slavery over time, often with restrictions and delays","sovereignty":"the right and power of a people or state to govern itself","exclusion":"the act of preventing certain people from participating or accessing rights","revolutionary ideals":"principles used to justify or inspire a major change in political authority","confederation":"an alliance of states or political communities retaining substantial independent authority","ratification":"formal approval that makes a proposed agreement or amendment effective","federal taxation":"taxes imposed by the national government under constitutional authority","northwest ordinance":"a 1787 law organizing governance and future statehood north of the Ohio River","virginia plan":"a Constitutional Convention proposal favoring representation based on population","new jersey plan":"a 1787 proposal supporting equal state representation in a central legislature","connecticut compromise":"the 1787 agreement establishing population-based House seats and equal state Senate seats","three-fifths clause":"a constitutional rule counting three-fifths of enslaved people for apportionment and direct taxation, without granting them rights","federalist":"a person supporting ratification of the proposed U.S. Constitution in 1787–1788","anti-federalist":"a critic of the proposed Constitution's concentrated federal power or lack of explicit protections","bill of rights":"the first ten amendments to the United States Constitution, ratified in 1791","federalism":"division of political authority between national and state governments","separation of powers":"division of governing functions among branches to limit concentrated authority","enumerated power":"a government power specifically granted in constitutional text","precedent":"a prior action or decision used as a guide in later situations","cabinet":"a group of senior executive advisers to the U.S. president","neutrality":"a position of nonparticipation in a conflict among other states","whiskey rebellion":"1794 resistance to a federal excise tax that tested national enforcement power","louisiana purchase":"the 1803 agreement acquiring French territorial claims west of the Mississippi","territorial claim":"a government's or people's assertion of authority over a land area","expedition":"an organized journey for exploration, military purposes, or research","impressment":"forcible recruitment of people, particularly sailors, into military service","tecumseh":"Shawnee leader who organized resistance to U.S. territorial expansion in the early 1800s","treaty of ghent":"the agreement signed in 1814 that ended the War of 1812 after ratification","fort mchenry":"Baltimore fort successfully defended against British attack in 1814","faction":"an organized political group sharing interests or positions","federalists":"members of an early U.S. political party emphasizing federal institutions and national financial policy","democratic-republicans":"an early U.S. political coalition associated with Jefferson and Madison","election of 1800":"presidential election bringing a transfer of power from Federalists to Democratic-Republicans","manifest destiny":"nineteenth-century U.S. expansionist ideology portraying continental growth as a national destiny","annexation":"the addition of territory to a state through political or military action","treaty of guadalupe hidalgo":"1848 agreement ending the U.S.–Mexican War and transferring major territorial claims","territorial expansion":"the widening of a nation's asserted boundaries or areas of control","indian removal act":"1830 U.S. law enabling coercive removal policies directed at Indigenous nations","worcester v. georgia":"1832 Supreme Court case limiting Georgia's authority within Cherokee territory","trail of tears":"name for the forced Cherokee removal of 1838–1839 and, more broadly, related Indigenous removal suffering","industrialization":"growth of production systems using machinery, factories, and concentrated labor","wage labor":"work compensated by wages rather than ownership of produced goods","lowell mills":"early textile factories in Lowell, Massachusetts, employing many young women","reform":"an organized effort to change laws, institutions, or social practices","seneca falls":"site of the 1848 women's rights convention in New York","declaration of sentiments":"1848 women's rights document demanding greater legal and political equality","suffrage":"the right to vote in political elections","antebellum":"the U.S. historical period before the Civil War, especially the decades preceding 1861","cotton kingdom":"term for the cotton-producing Deep South economy built on enslaved labor","domestic slave trade":"buying and selling enslaved people within the United States","coercion":"forcing a person to act through threats, violence, or restrictions","self-emancipation":"actions by enslaved people to secure their own freedom","abolitionism":"movements and efforts seeking the end of slavery","underground railroad":"informal networks and routes helping some enslaved people escape to freedom","frederick douglass":"formerly enslaved Black writer, speaker, and leading abolitionist","harriet tubman":"Black abolitionist who escaped slavery and helped others find freedom","compromise of 1850":"a series of federal measures concerning slavery and territories, including a stronger Fugitive Slave Act","fugitive slave act":"U.S. law requiring capture and return of people escaping enslavement, including the strengthened 1850 act","popular sovereignty":"the principle that political authority rests with the people; used controversially for territorial slavery decisions","kansas–nebraska act":"1854 law establishing Kansas and Nebraska territories and reopening slavery expansion disputes","sectionalism":"political division based on differing regional interests and identities","dred scott":"1857 Supreme Court decision denying Black national citizenship in its ruling and limiting congressional restriction of territorial slavery","secession declaration":"an official announcement by a state claiming withdrawal from a political union","slavery expansion":"the spread of legal enslavement into additional territories or regions","secession":"an asserted withdrawal by a state or political group from a larger political union","confederacy":"the Confederate States of America, a slaveholding rebellion formed by seceded southern states","fort sumter":"federal fort in Charleston Harbor attacked by Confederate forces in April 1861","border states":"slaveholding states that remained within the Union during the Civil War","antietam":"September 1862 battle in Maryland important to Union strategy and emancipation policy","gettysburg":"July 1863 Civil War battle in Pennsylvania ending Lee's invasion","vicksburg":"Mississippi city whose 1863 Union capture strengthened control of the Mississippi River","strategy":"a planned approach to achieving an objective with available resources","emancipation proclamation":"Lincoln's 1863 wartime proclamation declaring freedom in designated rebel-controlled areas","united states colored troops":"Black Union Army regiments organized under federal authority during the Civil War","citizenship":"legal or political membership in a state, with associated rights and obligations","home front":"civilian life and activity within a society during wartime","freedpeople":"individuals formerly held in slavery who obtained freedom","primary-source diary":"a personal daily account written near the time of the events it describes","reconstruction":"period after the Civil War involving rebuilding governments, abolition, and contested civil and political rights","freedmen's bureau":"federal agency founded in 1865 to assist formerly enslaved people and others during Reconstruction","labor contract":"agreement establishing conditions and obligations of paid work","thirteenth amendment":"1865 constitutional amendment abolishing slavery except as punishment for crime","fourteenth amendment":"1868 amendment establishing citizenship protections, due process and equal protection","fifteenth amendment":"1870 amendment barring voting-right denial based on race, color or previous servitude","equal protection":"constitutional requirement that states provide equal protection of the laws","black officeholding":"service by Black Americans in elected or appointed government positions","enforcement acts":"federal Reconstruction-era laws intended to protect civil and voting rights","ku klux klan":"white supremacist organization formed after the Civil War that used terror to oppose Black civil rights","voter intimidation":"threats or violence intended to discourage people from voting freely","compromise of 1877":"label commonly applied to disputed political understandings surrounding the 1876 election and the end of military Reconstruction","disenfranchisement":"the denial or removal of voting rights","jim crow":"systems of racial segregation and discrimination, particularly in the post-Reconstruction South","constitutional legacy":"the continuing influence of constitutional changes on later laws and political struggles"});
